local util = require("util")

-- The melta turret's art, generated by graphics/_blender/ (melta_render.py builds
-- and renders the model, assemble.py turns the renders into these sheets). Nothing
-- here is hand-drawn, so the numbers below must match what those scripts emit --
-- graphics/_blender/README.md records the contract.
--
-- Head (the rotating cannon):
--   256 x 256 frame, 64 directions, 1 frame each, line_length 1
--   8 files with 8 rows each -> 256 x 2048 per file (power of two both ways)
--   pivot is the frame centre, so shift is zero and the gun cannot wobble
--   scale 0.5 -> 128 px on screen per frame = 4 tiles, i.e. Factorio's 2x density
--
-- Base (the static emplacement) is a single 256 x 256 sprite at the same scale,
-- with its cast shadow baked in (melta-turret-base.png).
local FRAME = 256
local HEAD_FILES = 8
local ROWS_PER_FILE = 8

local head =
{
  width = FRAME,
  height = FRAME,
  frame_count = 1,
  direction_count = 64,
  line_length = 1,
  lines_per_file = ROWS_PER_FILE,
  slice = 1,
  scale = 0.5,
  shift = {0, 0},
  mipmap_count = 4,
  priority = "medium",
  filenames = {}
}

for i = 1, HEAD_FILES do
  head.filenames[i] = "__lilys-melta__/graphics/entity/melta-turret/melta-turret-head-" .. i .. ".png"
end

local function head_layers()
  return {layers = {table.deepcopy(head)}}
end

local base =
{
  filename = "__lilys-melta__/graphics/entity/melta-turret/melta-turret-base.png",
  width = FRAME,
  height = FRAME,
  frame_count = 1,
  scale = 0.5,
  shift = {0, 0},
  mipmap_count = 4,
  priority = "high"
}

-- Pipe sockets ---------------------------------------------------------------
-- A pipe is a 1-tile entity and the turret's collision box is 1.2, so the nearest tile
-- a pipe can occupy is 2.0 tiles out and its art stops at 1.5 -- past the hull's
-- silhouette on X (1.62) but short of it in Y (1.02-1.09, the camera is pitched). With
-- no socket the pipe just runs over the emplacement and reads as floating.
--
-- Vanilla's own answer is `pipe_covers`: a capped pipe end, drawn once per connected
-- side at the connection point. We reuse the vanilla art (the same 128x128 @ 0.5
-- sprites and shadow layers the flamethrower turret uses) so the socket matches every
-- pipe in the game; `pipecoverspictures()` is base's helper and __space-age__ calls it
-- too, so it follows base art changes. They draw at priority "extra-high", above the
-- hull's "high" -- no z-fighting, no render-layer juggling.
--
-- Nothing to configure per side: the engine draws the right variant from the
-- connection's direction. See C.pipe_reach for where they sit.
return
{
  head = head,
  base = base,
  pipe_covers = pipecoverspictures(),

  attacking_animation = head_layers(),
  prepared_animation = head_layers(),
  preparing_animation = head_layers(),
  ending_attack_animation = head_layers(),
  -- no fold/unfold: the cannon is always deployed, which keeps the head a single
  -- sheet instead of an 18-frame deploy strip nothing else would reuse
  folded_animation = head_layers(),
  folding_animation = head_layers()
}
